// Byte-string primitives.  A Python `bytes` value is modelled as a plain
// Array of JS numbers in the range 0..255.

/** Concatenate any number of byte arrays into a fresh byte array. */
export function bytesConcat(...parts) {
  const out = [];
  for (const p of parts) {
    for (let i = 0; i < p.length; i++) out.push(p[i]);
  }
  return out;
}

/** Python `v[start:stop]` (stop defaults to the end, negatives unsupported). */
export function bytesSlice(v, start, stop) {
  const n = v.length;
  let a = start === undefined ? 0 : start;
  let b = stop === undefined ? n : stop;
  if (a < 0) a = Math.max(0, n + a);
  if (b < 0) b = Math.max(0, n + b);
  if (a > n) a = n;
  if (b > n) b = n;
  const out = [];
  for (let i = a; i < b; i++) out.push(v[i]);
  return out;
}

/** Python `v.lstrip(bytes([byte]))`. */
export function bytesLstripByte(v, byte) {
  let i = 0;
  while (i < v.length && v[i] === byte) i++;
  return bytesSlice(v, i);
}

/** Python `v.rstrip()` for a bytes object: strips b' \t\n\r\x0b\f'. */
const ASCII_BYTES_SPACE = new Set([0x20, 0x09, 0x0a, 0x0d, 0x0b, 0x0c]);
export function bytesRstrip(v) {
  let n = v.length;
  while (n > 0 && ASCII_BYTES_SPACE.has(v[n - 1])) n--;
  return bytesSlice(v, 0, n);
}

/** Python `bytes(n)` -- n NUL bytes. */
export function bytesZeros(n) {
  const out = [];
  for (let i = 0; i < n; i++) out.push(0);
  return out;
}

/** Python `bytes(reversed(v))`. */
export function bytesReversed(v) {
  const out = [];
  for (let i = v.length - 1; i >= 0; i--) out.push(v[i]);
  return out;
}

export function bytesEqual(a, b) {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;
  return true;
}

/** Python `int.from_bytes(v, 'big')` as a BigInt. */
export function intFromBytesBig(v) {
  let acc = 0n;
  for (let i = 0; i < v.length; i++) acc = (acc << 8n) | BigInt(v[i]);
  return acc;
}

/** Interpret each JS code unit of a latin-1 decoded string as one byte. */
export function latin1ToBytes(s) {
  const out = [];
  for (let i = 0; i < s.length; i++) out.push(s.charCodeAt(i) & 0xff);
  return out;
}

// The slices of the Unicode character database that CPython's behaviour depends
// on here: `Py_UNICODE_ISSPACE`, `Py_UNICODE_ISPRINTABLE` and the decimal digit
// value used by `int()`.

// Py_UNICODE_ISSPACE: the ASCII half comes from CPython's _Py_ascii_whitespace
// table, the rest from the Zs/Zl/Zp categories plus U+0085.
const SPACE_ASCII = new Set([
  0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x1f, 0x20,
]);
const SPACE_WIDE = new Set([
  0x85, 0xa0, 0x1680,
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
  0x2006, 0x2007, 0x2008, 0x2009, 0x200a,
  0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
]);

/** True when CPython would treat this code point as whitespace. */
export function isPySpace(cp) {
  if (cp < 128) return SPACE_ASCII.has(cp);
  return SPACE_WIDE.has(cp);
}

// Py_UNICODE_ISPRINTABLE: printable iff the code point is U+0020 or its general
// category does not start with C (Cc/Cf/Cs/Co/Cn) or Z (Zs/Zl/Zp).
const NON_PRINTABLE_RE = /[\p{C}\p{Z}]/u;

export function isPyPrintable(cp) {
  if (cp === 0x20) return true;
  let ch;
  if (cp >= 0xd800 && cp <= 0xdfff) return false; // Cs, lone surrogate
  try {
    ch = String.fromCodePoint(cp);
  } catch (e) {
    return false;
  }
  return !NON_PRINTABLE_RE.test(ch);
}

// Every maximal run of category-Nd code points in Unicode is a whole number of
// 10-code-point decimal digit sets, each starting at its own "zero".  These are
// those zeros; the decimal value of a digit is its offset from its zero.
const ND_ZEROS = [
  48, 1632, 1776, 1984, 2406, 2534, 2662, 2790, 2918, 3046,
  3174, 3302, 3430, 3558, 3664, 3792, 3872, 4160, 4240, 6112,
  6160, 6470, 6608, 6784, 6800, 6992, 7088, 7232, 7248, 42528,
  43216, 43264, 43472, 43504, 43600, 44016, 65296, 66720, 68912, 69734,
  69872, 69942, 70096, 70384, 70736, 70864, 71248, 71360, 71472, 71904,
  72016, 72784, 73040, 73120, 73552, 92768, 92864, 93008, 120782, 120792,
  120802, 120812, 120822, 123200, 123632, 124144, 125264, 130032,
];

/**
 * CPython's Py_UNICODE_TODECIMAL: the decimal value of `cp`, or -1 when the
 * code point has no decimal digit value.
 */
export function decimalDigitValue(cp) {
  if (cp >= 0x30 && cp <= 0x39) return cp - 0x30;
  let lo = 0;
  let hi = ND_ZEROS.length - 1;
  let best = -1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (ND_ZEROS[mid] <= cp) {
      best = ND_ZEROS[mid];
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  if (best < 0) return -1;
  const d = cp - best;
  return d >= 0 && d <= 9 ? d : -1;
}

// Python `str` helpers that need CPython's unicode whitespace notion.

import { isPySpace } from './unidata.mjs';

/**
 * Decompose a JS string into an array of code points.  Unpaired surrogates
 * (which is how argv bytes recovered with surrogateescape are represented)
 * come through as their own single code point, exactly as in CPython.
 */
export function toCodePoints(s) {
  const out = [];
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff && i + 1 < s.length) {
      const d = s.charCodeAt(i + 1);
      if (d >= 0xdc00 && d <= 0xdfff) {
        out.push(0x10000 + ((c - 0xd800) << 10) + (d - 0xdc00));
        i++;
        continue;
      }
    }
    out.push(c);
  }
  return out;
}

/** Rebuild a JS string from an array of code points. */
export function fromCodePoints(cps) {
  let s = '';
  for (const cp of cps) {
    if (cp <= 0xffff) s += String.fromCharCode(cp);
    else {
      const v = cp - 0x10000;
      s += String.fromCharCode(0xd800 + (v >> 10), 0xdc00 + (v & 0x3ff));
    }
  }
  return s;
}

/** Python `str.rstrip()` with no argument. */
export function strRstrip(s) {
  const cps = toCodePoints(s);
  let n = cps.length;
  while (n > 0 && isPySpace(cps[n - 1])) n--;
  return fromCodePoints(cps.slice(0, n));
}

// Exception analogues for the handful of CPython exceptions this program can
// raise, plus the traceback rendering that PyInstaller-frozen scripts produce.

import { strRepr } from './pyrepr.mjs';
import { fromCodePoints } from './pystr.mjs';

/** Base class carrying the Python-side traceback frames. */
export class PyException extends Error {
  constructor(typeName) {
    super(typeName);
    this.typeName = typeName;
    this.frames = [];
  }

  /** The `str()` of the exception, i.e. the text after `TypeName: `. */
  pyStr() {
    return '';
  }
}

export class PyValueError extends PyException {
  constructor(message) {
    super('ValueError');
    this.messageText = message;
  }

  pyStr() {
    return this.messageText;
  }
}

export class PyUnicodeEncodeError extends PyException {
  /**
   * @param {string} encoding  e.g. 'utf-8' or 'ascii'
   * @param {number[]} objectCps  the offending string, as code points
   * @param {number} start  first bad code point index
   * @param {number} end    one past the last bad code point index
   * @param {string} reason
   */
  constructor(encoding, objectCps, start, end, reason) {
    super('UnicodeEncodeError');
    this.encoding = encoding;
    this.objectCps = objectCps;
    this.start = start;
    this.end = end;
    this.reason = reason;
  }

  pyStr() {
    if (this.start < this.objectCps.length && this.end === this.start + 1) {
      const bad = this.objectCps[this.start];
      let esc;
      if (bad <= 0xff) esc = '\\x' + hex(bad, 2);
      else if (bad <= 0xffff) esc = '\\u' + hex(bad, 4);
      else esc = '\\U' + hex(bad, 8);
      return (
        "'" + this.encoding + "' codec can't encode character '" + esc +
        "' in position " + this.start + ': ' + this.reason
      );
    }
    return (
      "'" + this.encoding + "' codec can't encode characters in position " +
      this.start + '-' + (this.end - 1) + ': ' + this.reason
    );
  }
}

function hex(n, width) {
  let s = n.toString(16);
  while (s.length < width) s = '0' + s;
  return s;
}

/** Prepend a `File "...", line N, in NAME` frame as the exception unwinds. */
export function withFrame(file, line, func, fn) {
  try {
    return fn();
  } catch (e) {
    if (e instanceof PyException) e.frames.unshift({ file, line, func });
    throw e;
  }
}

/** Render the full CPython traceback text (including the trailing newline). */
export function formatTraceback(exc) {
  let out = 'Traceback (most recent call last):\n';
  for (const f of exc.frames) {
    out += '  File "' + f.file + '", line ' + f.line + ', in ' + f.func + '\n';
  }
  const detail = exc.pyStr();
  out += exc.typeName + (detail ? ': ' + detail : '') + '\n';
  return out;
}

/** The line PyInstaller's bootloader appends after an unhandled exception. */
export function formatPyiFooter(pid) {
  return (
    '[PYI-' + pid + ":ERROR] Failed to execute script 'test19' due to " +
    'unhandled exception!\n'
  );
}

/** `ValueError("Invalid character {!r}".format(chr(byte)))`. */
export function invalidCharacterError(byte) {
  return new PyValueError(
    'Invalid character ' + strRepr(fromCodePoints([byte]))
