}

// CPython's `repr()` for `bytes` and `str` objects.

import { toCodePoints } from './pystr.mjs';
import { isPyPrintable } from './unidata.mjs';

function hex2(n) {
  const s = n.toString(16);
  return s.length < 2 ? '0' + s : s;
}

function hexN(n, width) {
  let s = n.toString(16);
  while (s.length < width) s = '0' + s;
  return s;
}

/** `repr(bytes_value)` for a byte array. */
export function bytesRepr(v) {
  let squote = 0;
  let dquote = 0;
  for (const b of v) {
    if (b === 0x27) squote++;
    else if (b === 0x22) dquote++;
  }
  let quote = 0x27;
  if (squote && !dquote) quote = 0x22;

  let out = 'b' + String.fromCharCode(quote);
  for (const c of v) {
    if (c === quote || c === 0x5c) out += '\\' + String.fromCharCode(c);
    else if (c === 0x09) out += '\\t';
    else if (c === 0x0a) out += '\\n';
    else if (c === 0x0d) out += '\\r';
    else if (c < 0x20 || c >= 0x7f) out += '\\x' + hex2(c);
    else out += String.fromCharCode(c);
  }
  return out + String.fromCharCode(quote);
}

/** `repr(str_value)`. */
export function strRepr(s) {
  const cps = toCodePoints(s);
  let squote = 0;
  let dquote = 0;
  for (const c of cps) {
    if (c === 0x27) squote++;
    else if (c === 0x22) dquote++;
  }
  let quote = 0x27;
  if (squote && !dquote) quote = 0x22;

  let out = String.fromCharCode(quote);
  for (const ch of cps) {
    if (ch === quote || ch === 0x5c) out += '\\' + String.fromCharCode(ch);
    else if (ch === 0x09) out += '\\t';
    else if (ch === 0x0a) out += '\\n';
    else if (ch === 0x0d) out += '\\r';
    else if (ch < 0x20 || ch === 0x7f) out += '\\x' + hex2(ch);
    else if (ch < 0x7f) out += String.fromCharCode(ch);
    else if (!isPyPrintable(ch)) {
      if (ch <= 0xff) out += '\\x' + hexN(ch, 2);
      else if (ch <= 0xffff) out += '\\u' + hexN(ch, 4);
      else out += '\\U' + hexN(ch, 8);
    } else if (ch <= 0xffff) out += String.fromCharCode(ch);
    else {
      const v = ch - 0x10000;
      out += String.fromCharCode(0xd800 + (v >> 10), 0xdc00 + (v & 0x3ff));
    }
  }
  return out + String.fromCharCode(quote);
}

// UTF-8 / ASCII codecs with CPython semantics, including the `surrogateescape`
// error handler used when decoding argv and the exceptions raised on encode.

import { toCodePoints } from './pystr.mjs';
import { PyUnicodeEncodeError } from './pyerrors.mjs';

/**
 * Walk a byte array as UTF-8.  `onChar(cp)` is called for every well-formed
 * sequence; `onError(start, end)` for every maximal ill-formed subsequence
 * (the same partitioning CPython and the WHATWG decoder both use).
 */
function walkUtf8(bytes, onChar, onError) {
  const n = bytes.length;
  let i = 0;
  while (i < n) {
    const b0 = bytes[i];
    if (b0 <= 0x7f) {
      onChar(b0);
      i++;
      continue;
    }
    let need;
    let lo;
    let hi;
    if (b0 >= 0xc2 && b0 <= 0xdf) { need = 1; lo = 0x80; hi = 0xbf; }
    else if (b0 === 0xe0) { need = 2; lo = 0xa0; hi = 0xbf; }
    else if (b0 >= 0xe1 && b0 <= 0xec) { need = 2; lo = 0x80; hi = 0xbf; }
    else if (b0 === 0xed) { need = 2; lo = 0x80; hi = 0x9f; }
    else if (b0 >= 0xee && b0 <= 0xef) { need = 2; lo = 0x80; hi = 0xbf; }
    else if (b0 === 0xf0) { need = 3; lo = 0x90; hi = 0xbf; }
    else if (b0 >= 0xf1 && b0 <= 0xf3) { need = 3; lo = 0x80; hi = 0xbf; }
    else if (b0 === 0xf4) { need = 3; lo = 0x80; hi = 0x8f; }
    else {
      onError(i, i + 1);
      i++;
      continue;
    }
    let cp = b0 & (need === 1 ? 0x1f : need === 2 ? 0x0f : 0x07);
    let j = i + 1;
    let ok = true;
    for (let k = 0; k < need; k++) {
      if (j >= n) { ok = false; break; }
      const b = bytes[j];
      const l = k === 0 ? lo : 0x80;
      const h = k === 0 ? hi : 0xbf;
      if (b < l || b > h) { ok = false; break; }
      cp = (cp << 6) | (b & 0x3f);
      j++;
    }
    if (!ok) {
      onError(i, j);
      i = j;
      continue;
    }
    onChar(cp);
    i = j;
  }
}

/** `bytes.decode('utf-8', 'surrogateescape')`. */
export function decodeUtf8SurrogateEscape(bytes) {
  const cps = [];
  walkUtf8(
    bytes,
    (cp) => cps.push(cp),
    (start, end) => {
      for (let k = start; k < end; k++) cps.push(0xdc00 + bytes[k]);
    }
  );
  return cpsToString(cps);
}

/** `bytes.decode('utf-8', 'replace')` -- what Node itself does to argv. */
export function decodeUtf8Replace(bytes) {
  const cps = [];
  walkUtf8(
    bytes,
    (cp) => cps.push(cp),
    () => cps.push(0xfffd)
  );
  return cpsToString(cps);
}

function cpsToString(cps) {
  let s = '';
  for (const cp of cps) {
    if (cp <= 0xffff) s += String.fromCharCode(cp);
    else {
      const v = cp - 0x10000;
      s += String.fromCharCode(0xd800 + (v >> 10), 0xdc00 + (v & 0x3ff));
    }
  }
  return s;
}

function encodeCodePoint(cp, out) {
  if (cp <= 0x7f) out.push(cp);
  else if (cp <= 0x7ff) {
    out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
  } else if (cp <= 0xffff) {
    out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
  } else {
    out.push(
      0xf0 | (cp >> 18),
      0x80 | ((cp >> 12) & 0x3f),
      0x80 | ((cp >> 6) & 0x3f),
      0x80 | (cp & 0x3f)
    );
  }
