/** `str.encode()` -- UTF-8, strict.  Raises on unpaired surrogates. */
export function encodeUtf8Strict(s) {
  const cps = toCodePoints(s);
  const out = [];
  for (let i = 0; i < cps.length; i++) {
    const cp = cps[i];
    if (cp >= 0xd800 && cp <= 0xdfff) {
      let end = i + 1;
      while (end < cps.length && cps[end] >= 0xd800 && cps[end] <= 0xdfff) end++;
      throw new PyUnicodeEncodeError('utf-8', cps, i, end, 'surrogates not allowed');
    }
    encodeCodePoint(cp, out);
  }
  return out;
}

/** `str.encode('ascii')` -- strict. */
export function encodeAsciiStrict(s) {
  const cps = toCodePoints(s);
  const out = [];
  for (let i = 0; i < cps.length; i++) {
    const cp = cps[i];
    if (cp >= 0x80) {
      let end = i + 1;
      while (end < cps.length && cps[end] >= 0x80) end++;
      throw new PyUnicodeEncodeError(
        'ascii', cps, i, end, 'ordinal not in range(128)'
      );
    }
    out.push(cp);
  }
  return out;
}

/**
 * `str.encode('utf-8', 'backslashreplace')` -- what CPython's sys.stderr does
 * with the unpaired surrogates that surrogateescape can leave behind.
 */
export function encodeUtf8Backslashreplace(s) {
  const cps = toCodePoints(s);
  const out = [];
  for (const cp of cps) {
    if (cp >= 0xd800 && cp <= 0xdfff) {
      const esc = '\\u' + cp.toString(16).padStart(4, '0');
      for (let i = 0; i < esc.length; i++) out.push(esc.charCodeAt(i));
    } else encodeCodePoint(cp, out);
  }
  return out;
}

// CPython's `int(str)` parser: unicode whitespace on either side, an optional
// sign, unicode decimal digits and `_` separators strictly between digits.

import { toCodePoints } from './pystr.mjs';
import { isPySpace, decimalDigitValue } from './unidata.mjs';

/**
 * @returns {bigint|null} the parsed value, or null when CPython's `int()`
 *   would raise ValueError.
 */
export function pyIntFromString(s) {
  const cps = toCodePoints(s);
  let i = 0;
  let j = cps.length;
  while (i < j && isPySpace(cps[i])) i++;
  while (j > i && isPySpace(cps[j - 1])) j--;

  let negative = false;
  if (i < j && (cps[i] === 0x2b || cps[i] === 0x2d)) {
    negative = cps[i] === 0x2d;
    i++;
  }

  let digits = '';
  let prevWasDigit = false;
  for (let k = i; k < j; k++) {
    const cp = cps[k];
    if (cp === 0x5f) {
      if (!prevWasDigit) return null;
      prevWasDigit = false;
      continue;
    }
    const d = decimalDigitValue(cp);
    if (d < 0) return null;
    digits += String(d);
    prevWasDigit = true;
  }
  if (digits.length === 0 || !prevWasDigit) return null;

  const value = BigInt(digits);
  return negative ? -value : value;
