    (bitLenHi >>> 24) & 0xff, (bitLenHi >>> 16) & 0xff,
    (bitLenHi >>> 8) & 0xff, bitLenHi & 0xff,
    (bitLenLo >>> 24) & 0xff, (bitLenLo >>> 16) & 0xff,
    (bitLenLo >>> 8) & 0xff, bitLenLo & 0xff
