      g = f;
      f = e;
      e = (d + temp1) >>> 0;
      d = c;
      c = b;
      b = a;
      a = (temp1 + temp2) >>> 0;
    }
    h[0] = (h[0] + a) >>> 0;
    h[1] = (h[1] + b) >>> 0;
    h[2] = (h[2] + c) >>> 0;
    h[3] = (h[3] + d) >>> 0;
    h[4] = (h[4] + e) >>> 0;
    h[5] = (h[5] + f) >>> 0;
    h[6] = (h[6] + g) >>> 0;
    h[7] = (h[7] + hh) >>> 0;
  }

  const out = [];
  for (const word of h) {
    out.push((word >>> 24) & 0xff, (word >>> 16) & 0xff, (word >>> 8) & 0xff, word & 0xff);
  }
  return out;
}

// A faithful port of the `base58` package's bitcoin-alphabet functions,
// including the exact source line numbers its tracebacks report.

import {
  bytesConcat, bytesSlice, bytesLstripByte, bytesRstrip, bytesZeros,
  bytesReversed, bytesEqual, intFromBytesBig,
} from './pybytes.mjs';
import { encodeAsciiStrict } from './pycodec.mjs';
import { strRstrip } from './pystr.mjs';
import { sha256 } from './sha256.mjs';
import {
  PyValueError, invalidCharacterError, withFrame,
} from './pyerrors.mjs';

const MODULE = 'base58/__init__.py';

export const BITCOIN_ALPHABET =
  '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';

const ALPHABET = [];
for (let i = 0; i < BITCOIN_ALPHABET.length; i++) {
  ALPHABET.push(BITCOIN_ALPHABET.charCodeAt(i));
}
const BASE = BigInt(ALPHABET.length);

const INDEX = new Map();
for (let i = 0; i < ALPHABET.length; i++) INDEX.set(ALPHABET[i], i);

/** Python's floor `divmod` for BigInt (negative numerators floor downward). */
function divmod(n, d) {
  let q = n / d;
  let r = n % d;
  if (r !== 0n && ((r < 0n) !== (d < 0n))) {
    q -= 1n;
    r += d;
  }
  return [q, r];
}

/**
 * `scrub_input(v)`: a str is ascii-encoded, bytes pass through.  The
 * UnicodeEncodeError surfaces as a frame at line 30.
 */
export function scrubInput(v) {
  if (typeof v === 'string') {
    return withFrame(MODULE, 30, 'scrub_input', () => encodeAsciiStrict(v));
  }
  return v;
}

/** `b58encode_int(i, default_one=True)` -> bytes. */
export function b58encodeInt(i, defaultOne = true) {
  if (i === 0n && defaultOne) return [ALPHABET[0]];
  let acc = i;
  const out = [];
  // NOTE: a negative `i` never reaches zero under floor division, exactly as in
  // CPython -- the loop is meant to spin forever.
  while (acc !== 0n) {
    const [q, r] = divmod(acc, BASE);
    acc = q;
    out.unshift(ALPHABET[Number(r)]);
  }
  return out;
}

/** `b58encode(v)` -> bytes. */
export function b58encode(v) {
  const scrubbed = scrubInput(v);
  const origlen = scrubbed.length;
  const stripped = bytesLstripByte(scrubbed, 0);
  const newlen = stripped.length;
  const acc = intFromBytesBig(stripped);
  const ones = [];
  for (let i = 0; i < origlen - newlen; i++) ones.push(ALPHABET[0]);
  return bytesConcat(ones, b58encodeInt(acc, false));
}

/** `b58decode_int(v)` -> bigint.  Raises ValueError at line 104. */
export function b58decodeInt(v) {
  let value = typeof v === 'string' ? strRstrip(v) : bytesRstrip(v);
  value = scrubInput(value);
  let decimal = 0n;
  for (const char of value) {
    const idx = INDEX.get(char);
    if (idx === undefined) {
      throw withFrame(MODULE, 104, 'b58decode_int', () => {
        throw invalidCharacterError(char);
      });
    }
    decimal = decimal * BASE + BigInt(idx);
  }
  return decimal;
}

/** `b58decode(v)` -> bytes. */
export function b58decode(v) {
  let value = typeof v === 'string' ? strRstrip(v) : bytesRstrip(v);
  value = withFrame(MODULE, 118, 'b58decode', () => scrubInput(value));

  const origlen = value.length;
  const stripped = bytesLstripByte(value, ALPHABET[0]);
  const newlen = stripped.length;

  let acc = withFrame(MODULE, 124, 'b58decode', () => b58decodeInt(stripped));

  const result = [];
  while (acc > 0n) {
    const [q, r] = divmod(acc, 256n);
    acc = q;
    result.push(Number(r));
  }
  return bytesConcat(bytesZeros(origlen - newlen), bytesReversed(result));
}

/** `b58encode_check(v)` -> bytes. */
export function b58encodeCheck(v) {
  const scrubbed = scrubInput(v);
  const digest = sha256(sha256(scrubbed));
  return b58encode(bytesConcat(scrubbed, bytesSlice(digest, 0, 4)));
}

/** `b58decode_check(v)` -> bytes.  Raises ValueError('Invalid checksum'). */
export function b58decodeCheck(v) {
  const result = b58decode(v);
  const payload = bytesSlice(result, 0, result.length - 4);
  const checksum = bytesSlice(result, result.length - 4);
  const expected = bytesSlice(sha256(sha256(payload)), 0, 4);
  if (!bytesEqual(checksum, expected)) {
    throw withFrame(MODULE, 145, 'b58decode_check', () => {
      throw new PyValueError('Invalid checksum');
    });
  }
  return payload;
}

