// Blocking writes to fd 1 / fd 2 with CPython's stream error handlers
// (stdout: strict, stderr: backslashreplace), so nothing is lost on exit.

import * as fs from 'node:fs';
import { encodeUtf8Strict, encodeUtf8Backslashreplace } from './pycodec.mjs';

function writeAllBytes(fd, bytes) {
  if (bytes.length === 0) return;
  let chunk = '';
  for (const b of bytes) chunk += String.fromCharCode(b);
  let offset = 0;
  while (offset < chunk.length) {
    let written;
    try {
      written = fs.writeSync(fd, chunk.slice(offset), null, 'latin1');
    } catch (e) {
      if (e && (e.code === 'EAGAIN' || e.code === 'EINTR')) continue;
      if (e && e.code === 'EPIPE') return;
      throw e;
    }
    if (!(written > 0)) return;
    offset += written;
  }
}

/** `sys.stdout.write(text)` followed by a flush. */
export function writeStdout(text) {
  writeAllBytes(1, encodeUtf8Strict(text));
}

/** `sys.stderr.write(text)` followed by a flush. */
export function writeStderr(text) {
  writeAllBytes(2, encodeUtf8Backslashreplace(text));
}

// Recover the true argv bytes CPython would have seen.
//
// Node has already decoded argv as UTF-8 with U+FFFD substitution, which throws
// away the distinction between a real U+FFFD and an invalid byte.  CPython
// instead decodes with `surrogateescape`, mapping byte 0xNN to U+DCNN, and those
// lone surrogates are what later fail to re-encode.  `/proc/self/cmdline` still
// has the original bytes.

import * as fs from 'node:fs';
import { latin1ToBytes } from './pybytes.mjs';
import { decodeUtf8SurrogateEscape, decodeUtf8Replace } from './pycodec.mjs';

/**
 * @returns {string[]} the program arguments, with invalid UTF-8 bytes mapped
 *   into the U+DC80..U+DCFF surrogateescape range.  Falls back to
 *   `process.argv.slice(2)` whenever recovery cannot be verified.
 */
export function recoverArgs() {
  const lossy = process.argv.slice(2);
  const wanted = process.argv.length - 2;
  if (wanted <= 0) return lossy;

  let raw;
  try {
    raw = fs.readFileSync('/proc/self/cmdline', 'latin1');
  } catch (e) {
    return lossy;
  }

  const records = raw.split('\0');
  if (records.length > 0 && records[records.length - 1] === '') records.pop();
  if (records.length < wanted) return lossy;

  const tail = records.slice(records.length - wanted);
  const out = [];
  for (let i = 0; i < wanted; i++) {
    const bytes = latin1ToBytes(tail[i]);
    if (decodeUtf8Replace(bytes) !== lossy[i]) return lossy;
    out.push(decodeUtf8SurrogateEscape(bytes));
  }
  return out;
}

// The slice of `argparse` this program exercises: six required value-taking
// long options plus -h/--help, with CPython 3.12's usage/help formatting,
// option-string resolution and error messages.

import { writeStdout, writeStderr } from './pyio.mjs';
import { strRepr } from './pyrepr.mjs';
import { toCodePoints } from './pystr.mjs';
import { pyIntFromString } from './pyint.mjs';

const PREFIX_CHARS = '-';
const NEGATIVE_NUMBER_RE = /^-[\p{Nd}]+$|^-[\p{Nd}]*\.[\p{Nd}]+$/u;
const PART_RE = /\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+/g;

/** The parser's actions, in declaration order (which the errors depend on). */
export function buildActions() {
  const actions = [
    {
      dest: 'help',
      optionStrings: ['-h', '--help'],
      nargs: 0,
      required: false,
      type: null,
      metavar: null,
      help: 'show this help message and exit',
    },
  ];
  for (const dest of ['a', 'b', 'c', 'd', 'e', 'f']) {
    actions.push({
      dest,
      optionStrings: ['--' + dest],
      nargs: null,
      required: true,
      type: dest === 'e' || dest === 'f' ? 'int' : 'str',
      metavar: dest.toUpperCase(),
      help: '',
    });
  }
  return actions;
}

/* ------------------------------------------------------------------ layout */

/** shutil.get_terminal_size().columns, the way CPython computes it. */
export function terminalColumns() {
  let columns = 0;
  const env = process.env.COLUMNS;
  if (env !== undefined) {
    const parsed = pyIntFromString(env);
    if (parsed !== null) {
      const n = Number(parsed);
      columns = Number.isFinite(n) ? n : 0;
    }
  }
  if (columns <= 0) {
    const tty = process.stdout ? process.stdout.columns : undefined;
    columns = typeof tty === 'number' && tty > 0 ? tty : 80;
  }
  return columns;
}

function invocation(action) {
  if (action.nargs === 0) return action.optionStrings.join(', ');
  return action.optionStrings.map((o) => o + ' ' + action.metavar).join(', ');
}

function usagePart(action) {
  const first = action.optionStrings[0];
  const part = action.nargs === 0 ? first : first + ' ' + action.metavar;
  return action.required ? part : '[' + part + ']';
}

/** textwrap.wrap(), greedy, with whitespace collapsed first. */
function wrapText(text, width) {
  const normalized = text.replace(/[ \t\n\r\f\v]+/g, ' ').trim();
  if (normalized === '') return [];
  const lines = [];
  let current = '';
  for (const word of normalized.split(' ')) {
    if (current === '') current = word;
    else if (current.length + 1 + word.length <= width) current += ' ' + word;
    else {
      lines.push(current);
      current = word;
    }
  }
  if (current !== '') lines.push(current);
  return lines;
}

function formatUsageBlock(prog, actions, width) {
  const prefix = 'usage: ';
  const actionUsage = actions.map(usagePart).join(' ');
  let usage = [prog, actionUsage].filter((s) => s).join(' ');
  const textWidth = width;

  if (prefix.length + usage.length > textWidth) {
    const optParts = actionUsage.match(PART_RE) || [];
    const posParts = [];

    const getLines = (parts, indent, pre) => {
      const lines = [];
      let line = [];
      let lineLen = (pre !== undefined ? pre.length : indent.length) - 1;
      for (const part of parts) {
        if (lineLen + 1 + part.length > textWidth && line.length) {
          lines.push(indent + line.join(' '));
          line = [];
          lineLen = indent.length - 1;
        }
        line.push(part);
        lineLen += 1 + part.length;
      }
      if (line.length) lines.push(indent + line.join(' '));
      if (pre !== undefined && lines.length) {
        lines[0] = lines[0].slice(indent.length);
      }
      return lines;
    };

    let lines;
    if (prefix.length + prog.length <= 0.75 * textWidth) {
      const indent = ' '.repeat(prefix.length + prog.length + 1);
      if (optParts.length) {
        lines = getLines([prog].concat(optParts), indent, prefix);
        lines = lines.concat(getLines(posParts, indent));
      } else if (posParts.length) {
        lines = getLines([prog].concat(posParts), indent, prefix);
      } else {
        lines = [prog];
      }
    } else {
      const indent = ' '.repeat(prefix.length);
      lines = getLines(optParts.concat(posParts), indent);
      if (lines.length > 1) {
        lines = getLines(optParts, indent).concat(getLines(posParts, indent));
      }
      lines = [prog].concat(lines);
    }
    usage = lines.join('\n');
  }
  return prefix + usage + '\n\n';
}

function finish(text) {
  if (!text) return text;
  return text.replace(/\n\n\n+/g, '\n\n').replace(/^\n+|\n+$/g, '') + '\n';
}

export function formatUsage(prog, actions, width) {
  return finish(formatUsageBlock(prog, actions, width));
}

export function formatHelp(prog, actions, width) {
  let text = formatUsageBlock(prog, actions, width);

  let maxLength = 0;
  for (const a of actions) {
    maxLength = Math.max(maxLength, invocation(a).length + 2);
  }
  const maxHelpPosition = Math.min(24, Math.max(width - 20, 4));
  const helpPosition = Math.min(maxLength + 2, maxHelpPosition);
  const helpWidth = Math.max(width - helpPosition, 11);
  const actionWidth = helpPosition - 2 - 2;

  let items = '';
  for (const action of actions) {
    let header = invocation(action);
    let indentFirst = 0;
    if (!action.help) {
      header = '  ' + header + '\n';
    } else if (header.length <= actionWidth) {
      header = '  ' + header.padEnd(actionWidth) + '  ';
    } else {
      header = '  ' + header + '\n';
      indentFirst = helpPosition;
    }
    let part = header;
    if (action.help && action.help.trim()) {
      const lines = wrapText(action.help, helpWidth);
      if (lines.length) {
        part += ' '.repeat(indentFirst) + lines[0] + '\n';
        for (const line of lines.slice(1)) {
          part += ' '.repeat(helpPosition) + line + '\n';
        }
      }
    } else if (!header.endsWith('\n')) {
      part += '\n';
    }
    items += part;
  }

  text += '\n' + 'options:\n' + items + '\n';
  return finish(text);
}

/* ------------------------------------------------------------------ parsing */

class ArgumentError extends Error {
  constructor(action, message) {
    super(message);
    this.actionName = action ? action.optionStrings.join('/') : null;
    this.detail = message;
  }

  render() {
    return this.actionName
      ? 'argument ' + this.actionName + ': ' + this.detail
      : this.detail;
  }
}

/**
 * Parse `argStrings`, exiting the process on -h (0) or any argparse error (2).
 *
 * @returns {{a: string, b: string, c: string, d: string, e: bigint, f: bigint}}
 */
export function parseArgs(prog, argStrings) {
  const actions = buildActions();
  const width = terminalColumns() - 2;

  const optionStringActions = new Map();
  for (const action of actions) {
    for (const optionString of action.optionStrings) {
      optionStringActions.set(optionString, action);
    }
  }

  const fail = (message) => {
    writeStderr(formatUsage(prog, actions, width));
    writeStderr(prog + ': error: ' + message + '\n');
    process.exit(2);
  };

  const showHelp = () => {
    writeStdout(formatHelp(prog, actions, width));
    process.exit(0);
  };

  const getOptionTuples = (optionString) => {
    const result = [];
    const c0 = optionString[0];
    const c1 = optionString[1];
    if (PREFIX_CHARS.includes(c0) && PREFIX_CHARS.includes(c1)) {
      let optionPrefix;
      let explicitArg;
      const eq = optionString.indexOf('=');
      if (eq >= 0) {
        optionPrefix = optionString.slice(0, eq);
        explicitArg = optionString.slice(eq + 1);
      } else {
        optionPrefix = optionString;
        explicitArg = null;
      }
      for (const [key, action] of optionStringActions) {
        if (key.startsWith(optionPrefix)) result.push([action, key, explicitArg]);
      }
    } else if (PREFIX_CHARS.includes(c0) && !PREFIX_CHARS.includes(c1)) {
      const optionPrefix = optionString;
      const shortOptionPrefix = optionString.slice(0, 2);
      const shortExplicitArg = optionString.slice(2);
      for (const [key, action] of optionStringActions) {
        if (key === shortOptionPrefix) {
          result.push([action, key, shortExplicitArg]);
        } else if (key.startsWith(optionPrefix)) {
          result.push([action, key, null]);
        }
      }
    } else {
      fail('unexpected option string: ' + optionString);
    }
    return result;
  };

  const parseOptional = (argString) => {
    if (argString === '') return null;
    if (!PREFIX_CHARS.includes(argString[0])) return null;
    if (optionStringActions.has(argString)) {
      return [optionStringActions.get(argString), argString, null];
    }
    if (toCodePoints(argString).length === 1) return null;
    const eq = argString.indexOf('=');
    if (eq >= 0) {
      const optionString = argString.slice(0, eq);
      if (optionStringActions.has(optionString)) {
        return [
          optionStringActions.get(optionString),
          optionString,
          argString.slice(eq + 1),
        ];
      }
    }
    const optionTuples = getOptionTuples(argString);
    if (optionTuples.length > 1) {
      const options = optionTuples.map((t) => t[1]).join(', ');
      fail('ambiguous option: ' + argString + ' could match ' + options);
    } else if (optionTuples.length === 1) {
      return optionTuples[0];
    }
    if (NEGATIVE_NUMBER_RE.test(argString)) return null;
    if (argString.includes(' ')) return null;
    return [null, argString, null];
  };

  // Classify every argument as an option ('O') or a plain value ('A'); the
  // first bare '--' turns everything that follows into plain values.
  const optionTupleAt = new Map();
  let pattern = '';
  for (let i = 0; i < argStrings.length; i++) {
    if (argStrings[i] === '--') {
      pattern += '-';
      for (let j = i + 1; j < argStrings.length; j++) pattern += 'A';
      break;
    }
    const tuple = parseOptional(argStrings[i]);
    if (tuple === null) pattern += 'A';
    else {
      optionTupleAt.set(i, tuple);
      pattern += 'O';
    }
  }

  const nargsPattern = (action) => {
    let p = action.nargs === 0 ? '(-*-*)' : '(-*A-*)';
    if (action.optionStrings.length) {
      p = p.split('-*').join('');
      p = p.split('-').join('');
    }
    return p;
  };

  const matchArgument = (action, argStringsPattern) => {
    const match = new RegExp('^' + nargsPattern(action)).exec(argStringsPattern);
    if (match === null) throw new ArgumentError(action, 'expected one argument');
    return match[1].length;
  };

  const getValue = (action, argString) => {
    if (action.type === 'int') {
      const value = pyIntFromString(argString);
      if (value === null) {
        throw new ArgumentError(
          action, 'invalid int value: ' + strRepr(argString)
        );
      }
      return value;
    }
    return argString;
  };

  const getValues = (action, rawStrings) => {
    const strings = rawStrings.slice();
    const dashdash = strings.indexOf('--');
    if (dashdash >= 0) strings.splice(dashdash, 1);
    if (strings.length === 1 && action.nargs === null) {
      return getValue(action, strings[0]);
    }
    return strings.map((s) => getValue(action, s));
  };

  const extras = [];
  const seen = new Set();
  const values = {};

  const takeAction = (action, argumentStrings) => {
    seen.add(action);
    const argumentValues = getValues(action, argumentStrings);
    if (action.dest === 'help') showHelp();
    else values[action.dest] = argumentValues;
  };

  const consumeOptional = (startIndex) => {
    let [action, optionString, explicitArg] = optionTupleAt.get(startIndex);
    const actionTuples = [];
    let stop = startIndex;
    for (;;) {
      if (action === null) {
        extras.push(argStrings[startIndex]);
        return startIndex + 1;
      }
      if (explicitArg !== null) {
        const argCount = matchArgument(action, 'A');
        if (
          argCount === 0 &&
          !PREFIX_CHARS.includes(optionString[1]) &&
          explicitArg !== ''
        ) {
          actionTuples.push([action, []]);
          const char = optionString[0];
          optionString = char + explicitArg[0];
          const newExplicitArg =
            explicitArg.slice(1) === '' ? null : explicitArg.slice(1);
          if (optionStringActions.has(optionString)) {
            action = optionStringActions.get(optionString);
            explicitArg = newExplicitArg;
          } else {
            extras.push(char + explicitArg);
            stop = startIndex + 1;
            break;
          }
        } else if (argCount === 1) {
          stop = startIndex + 1;
          actionTuples.push([action, [explicitArg]]);
          break;
        } else {
          throw new ArgumentError(
            action, 'ignored explicit argument ' + strRepr(explicitArg)
          );
