const B58 = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
const POOL = [
  'a', 'b', 'c', 'X', 'Y', 'Z', '0', '1', '9', ' ', '\t', '\n', '\r', '\v', '\f',
  'é', '中', '\u{1F600}', "'", '"', '\\', '~', '!', '@', '#', '​', '﻿',
  ' ', '　', '\x01', '\x7f', 'ÿ', 'Ā', '=', '-',
];
const B58POOL = [...B58, ' ', '\t', '0', 'O', 'I', 'l', '1'];
const INTPOOL = ['0', '1', '2', '9', '_', '+', '-', ' ', '١', '४', '４', 'x', '.', ''];

let seed = 987654321;
const rnd = () => ((seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff);
const pick = (arr) => arr[Math.floor(rnd() * arr.length)];
const mk = (n, arr) => { let r = ''; for (let i = 0; i < n; i++) r += pick(arr); return r; };

const cases = [];
for (let i = 0; i < 260; i++) {
  const a = mk(Math.floor(rnd() * 8), POOL);
  const b = mk(Math.floor(rnd() * 10), B58POOL);
  const c = mk(Math.floor(rnd() * 6), POOL);
  const d = mk(Math.floor(rnd() * 6), POOL);
  const e = rnd() < 0.25 ? mk(Math.floor(rnd() * 5), INTPOOL)
    : String(Math.floor(rnd() * 4294967296));
  const f = rnd() < 0.15 ? mk(Math.floor(rnd() * 4), INTPOOL)
    : String(Math.floor(rnd() * 1e12));
  cases.push(['--a', a, '--b', b, '--c', c, '--d', d, '--e', e, '--f', f]);
}
// drop cases containing NUL (cannot be passed through exec at all)
console.log(JSON.stringify(cases.filter((c) => !c.some((s) => s.includes('\0')))));
